llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, the closest retinoid analogue, has a systemic bioavailability of 40% at therapeutic dosing, directly supporting F ≥ 20% for the retinoid backbone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Tretinoin (all-trans retinoic acid) oral bioavailability is approximately 50% in humans, supporting that retinoid acids can exceed the 20% threshold despite poor solubility.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin, a close retinoid analogue, has an absolute oral bioavailability of approximately 60% (range 36–95%) after oral dosing, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Etretinate, a highly lipophilic retinoid ester with extremely low aqueous solubility, still achieves about 40% absolute oral bioavailability, showing that very lipophilic retinoids can exceed 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Paracetamol, which shares the p-hydroxyanilide substructure with the query, has high oral bioavailability (~82%), indicating the phenolic amide moiety is not inherently a bioavailability liability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "13-cis retinoic acid has been reported to have low and variable absolute bioavailability due to gut degradation, providing some contradictory evidence, but quantitative estimates for retinoids generally remain at or above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "All-trans retinoic acid in some oral formulations shows low and erratic bioavailability, but this largely reflects formulation and chronic-dosing variability rather than a consistent intrinsic F below 20%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a retinoid p-hydroxyanilide (fenretinide-like). Multiple close retinoid analogues—isotretinoin, tretinoin, acitretin, and etretinate—have absolute oral bioavailability values of roughly 40–72%, all above the 20% threshold, despite very low aqueous solubility. The p-hydroxyanilide substructure is shared with paracetamol, which is well absorbed. Reports of low/erratic retinoid bioavailability are formulation- or chronic-dosing-related and do not overturn the quantitative F estimates. Therefore predict high (F ≥ 20%) with moderate confidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for fenretinide (the query molecule) itself; evidence is from close retinoid analogues.",
    "Formulation and fed/fasted conditions for the query are unknown; high lipophilicity may require lipid-based formulation to achieve maximal absorption.",
    "Potential first-pass glucuronidation of the phenolic amide and possible amide hydrolysis are not directly quantified for this exact molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

